/* DocAppoint service worker.
 *
 * Deliberately hand-written rather than generated by next-pwa/workbox: this app
 * is on Next 16 + Turbopack, and those plugins historically lag new Next
 * releases. This is small enough to read in one sitting and has no build step.
 *
 * The guiding rule is that NOTHING personal or authenticated is ever written to
 * the cache. See shouldBypass() below.
 */

const VERSION = "docappoint-v1";
const STATIC_CACHE = `${VERSION}-static`;
const PAGE_CACHE = `${VERSION}-pages`;
const OFFLINE_URL = "/offline";

// Pages safe to serve from cache: public, identical for every visitor.
const CACHEABLE_PAGES = ["/home", "/all-appointments", "/signin", "/signup", OFFLINE_URL];

const PRECACHE = [
  OFFLINE_URL,
  "/manifest.webmanifest",
  "/icon-192.png",
  "/icon-512.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(STATIC_CACHE)
      // Individually, so one 404 can't fail the whole install.
      .then((cache) => Promise.allSettled(PRECACHE.map((u) => cache.add(u))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => !k.startsWith(VERSION)).map((k) => caches.delete(k)))
      )
      .then(() => self.clients.claim())
  );
});

/**
 * Anything that is per-user, mutating, or auth-bearing must go straight to the
 * network and never be stored. Caching any of this would mean one account's
 * data could be replayed to whoever opens the app next on a shared device.
 */
const shouldBypass = (request, url) => {
  if (request.method !== "GET") return true;              // never cache writes
  if (url.origin !== self.location.origin) return true;   // the Express API, Unsplash, Cloudinary
  if (url.pathname.startsWith("/api/")) return true;      // Better Auth lives here
  if (url.pathname.startsWith("/dashboard")) return true; // per-user pages
  if (url.pathname.startsWith("/doctors/")) return true;  // auth-gated detail pages
  if (url.pathname.startsWith("/reset-password")) return true; // one-time tokens
  if (url.search.includes("token=")) return true;
  if (request.headers.get("authorization")) return true;
  return false;
};

const isStaticAsset = (url) =>
  url.pathname.startsWith("/_next/static/") ||
  url.pathname.startsWith("/icon-") ||
  /\.(css|js|woff2?|png|jpg|jpeg|svg|ico|webp)$/.test(url.pathname);

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (shouldBypass(request, url)) return; // fall through to the network untouched

  // Hashed build output is immutable — cache-first is safe and fast.
  if (isStaticAsset(url)) {
    event.respondWith(
      caches.match(request).then(
        (hit) =>
          hit ||
          fetch(request).then((res) => {
            if (res.ok) {
              const copy = res.clone();
              caches.open(STATIC_CACHE).then((c) => c.put(request, copy));
            }
            return res;
          })
      )
    );
    return;
  }

  if (request.mode === "navigate") {
    const cacheable = CACHEABLE_PAGES.includes(url.pathname);

    event.respondWith(
      fetch(request)
        .then((res) => {
          if (cacheable && res.ok) {
            const copy = res.clone();
            caches.open(PAGE_CACHE).then((c) => c.put(request, copy));
          }
          return res;
        })
        .catch(async () => {
          // Offline: serve this page if we have it, otherwise the offline shell.
          const hit = cacheable ? await caches.match(request) : null;
          return hit || (await caches.match(OFFLINE_URL)) || Response.error();
        })
    );
  }
});

// Lets the page trigger an immediate update instead of waiting for a reload.
self.addEventListener("message", (event) => {
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});
